import { useId } from "react";
import type { IconProps } from "~/types";

const IndependenceMonument = ({
  size,
  width = size ?? 130,
  height = size ?? 240,
  className,
  ...props
}: IconProps) => {
  const uid = useId();
  const patternId = `${uid}-pattern`;
  const imageId = `${uid}-image`;

  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 130 240"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
      className={className}
      aria-hidden="true"
      {...props}
    >
      <rect width="130" height="240" fill={`url(#${patternId})`} />
      <defs>
        <pattern
          id={patternId}
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use
            xlinkHref={`#${imageId}`}
            transform="matrix(0.00129039 0 0 0.00069688 -0.716839 -0.68561)"
          />
        </pattern>
        <image
          id={imageId}
          width="1886"
          height="4096"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
        />
      </defs>
    </svg>
  );
};

export default IndependenceMonument;
